	test('fetchMessages calls the chat API endpoint including last known', () => {
		fetchMessages({
			token: 'XXTOKENXX',
			lastKnownMessageId: 1234,
			includeLastKnown: 1,
			threadId: 1111,
		}, {
			dummyOption: true,
		})

		expect(axios.get).toHaveBeenCalledWith(
			generateOcsUrl('apps/spreed/api/v1/chat/XXTOKENXX'),
			{
				dummyOption: true,
				params: {
					setReadMarker: 0,
					lookIntoFuture: 0,
					lastKnownMessageId: 1234,
					limit: CHAT.FETCH_LIMIT,
					includeLastKnown: 1,
					threadId: 1111,
					timeout: 0,
				},
			},
		)
