				params: {
					setReadMarker: 0,
					lookIntoFuture: 1,
					lastKnownMessageId: 1234,
					limit: CHAT.FETCH_LIMIT,
					includeLastKnown: 0,
					markNotificationsAsRead: 0,
				},
			},
		)
	})

